            self.privacy
                .generation
                .fetch_add(1, std::sync::atomic::Ordering::SeqCst);
        }
        for id in &file_ids {
            if delivery.erase_file(conv, *id)? {
                self.privacy
                    .generation
                    .fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            }
