    assert_eq!(
        sender
            .delivery
            .lock()
            .unwrap()
            .next_destination(None)
            .unwrap()
            .1
            .event_id,
        destination
    );
    worker.abort();
    let _ = worker.await;
    sender.runtime_work.close();
    tokio::time::timeout(Duration::from_secs(1), sender.runtime_work.drain())
        .await
        .unwrap();
