use crate::node::conversation::account_conversation_id;
use std::collections::{HashMap, HashSet};

// A disabled per-node atomic sink cannot call back into storage or Node locks.
// Only the explicitly traced erasure passes its sink into nested recovery.
#[cfg(test)]
pub(in crate::node) mod erase_diagnostics {
    use std::sync::atomic::{AtomicU8, Ordering};
    macro_rules! phases {
        ($($name:ident),+ $(,)?) => {
            #[derive(Clone, Copy)]
            #[repr(u8)]
            pub enum Phase { Disabled, $($name),+ }
            pub fn label(value: u8) -> &'static str {
                match value {
                    0 => "Disabled",
                    $(value if value == Phase::$name as u8 => stringify!($name),)+
                    _ => "Unknown",
                }
            }
        };
    }
    phases!(
        Armed,
        LogicalIdentity,
        ChannelIdentity,
        DeliveryWait,
        Recovery,
        RecoveryOwner,
        RecoverySync,
        RecoveryPrepare,
        RatchetWait,
        LogWait,
        SentWait,
        ReceivedWait,
        FilesWait,
        SenderWait,
        RecallCompletion,
        GroupCompletion,
        Replay,
        ReplayReturned,
        RecoveryTail,
        Aliases,
        FileRows,
        Suppression,
        Reactions,
        Cancel,
        ControlIds,
        ReseedFiles,
        ScanReceived,
        ScanFiles,
        ScanSent,
        RemoveRows,
        RemoveMedia,
        Finished
    );
    pub fn mark(slot: Option<&AtomicU8>, phase: Phase) {
        if let Some(slot) = slot
            && slot.load(Ordering::Relaxed) != 0
        {
            slot.store(phase as u8, Ordering::Relaxed);
        }
    }
    pub struct Observer {
        slot: std::sync::Arc<AtomicU8>,
        stop: std::sync::mpsc::Sender<()>,
        worker: Option<std::thread::JoinHandle<()>>,
    }
    impl Observer {
        pub fn start(slot: std::sync::Arc<AtomicU8>) -> Self {
            let (stop, stopped) = std::sync::mpsc::channel();
            let (ready, started) = std::sync::mpsc::sync_channel(1);
            slot.store(Phase::Armed as u8, Ordering::Relaxed);
            let observed = slot.clone();
            let worker = std::thread::spawn(move || {
                let clock = std::time::Instant::now();
                let _ = ready.send(());
                loop {
                    eprintln!(
                        "local erase stage={} elapsed_ms={}",
                        label(observed.load(Ordering::Relaxed)),
                        clock.elapsed().as_millis()
                    );
                    match stopped.recv_timeout(std::time::Duration::from_secs(1)) {
                        Err(std::sync::mpsc::RecvTimeoutError::Timeout) => {}
                        _ => break,
                    }
                }
            });
            let owner = Self {
                slot,
                stop,
                worker: Some(worker),
            };
            started
                .recv_timeout(std::time::Duration::from_secs(5))
                .expect("the independent erase observer starts before synchronous erasure");
            owner
        }
    }
    impl Drop for Observer {
        fn drop(&mut self) {
            self.slot.store(Phase::Disabled as u8, Ordering::Relaxed);
            let _ = self.stop.send(());
            if let Some(worker) = self.worker.take() {
                // The observer waits only for this channel and touches no Node locks.
                let _ = worker.join();
            }
        }
    }
    #[test]
    fn erase_observer_is_disabled_after_unwind_and_joins_its_worker() {
        let slot = std::sync::Arc::new(AtomicU8::new(0));
        mark(Some(&slot), Phase::Cancel);
        assert_eq!(
            slot.load(Ordering::Relaxed),
            0,
            "an unarmed sink remains disabled"
        );
        let weak = std::sync::Arc::downgrade(&slot);
        let result = std::panic::catch_unwind({
            let slot = slot.clone();
            move || {
                let _observer = Observer::start(slot.clone());
                mark(Some(&slot), Phase::Cancel);
                assert_eq!(label(slot.load(Ordering::Relaxed)), "Cancel");
                panic!("injected erase failure");
            }
        });
        assert!(result.is_err());
        assert_eq!(slot.load(Ordering::Relaxed), 0);
        assert_eq!(
            weak.strong_count(),
            1,
            "the joined worker releases its only sink clone"
        );
    }
}
